def match(orders):
    import heapq

    buy_heap = []   # max-heap via negative price: (-price, seq, id)
    sell_heap = []  # min-heap: (price, seq, id)
    book = {}       # id -> dict with side, price, qty, status, seq
    trades = []
    seq_counter = 0

    def add_resting(oid, side, price, qty, seq):
        book[oid] = {'side': side, 'price': price, 'qty': qty, 'status': 'active', 'seq': seq}
        if side == 'buy':
            heapq.heappush(buy_heap, (-price, seq, oid))
        else:
            heapq.heappush(sell_heap, (price, seq, oid))

    for order in orders:
        typ = order[0]

        if typ == 'cancel':
            oid = order[1]
            if oid in book and book[oid]['status'] == 'active':
                book[oid]['status'] = 'cancelled'
            continue

        if typ == 'limit':
            _, oid, side, price, qty = order
        elif typ == 'ioc':
            _, oid, side, price, qty = order
        elif typ == 'market':
            _, oid, side, qty = order
            price = None
        else:
            continue

        seq_counter += 1
        seq = seq_counter
        remaining = qty

        opp_heap = sell_heap if side == 'buy' else buy_heap

        while remaining > 0 and opp_heap:
            top = opp_heap[0]
            top_id = top[2]

            if top_id not in book or book[top_id]['status'] != 'active' or book[top_id]['qty'] <= 0:
                heapq.heappop(opp_heap)
                continue

            top_price = book[top_id]['price']

            if typ != 'market':
                if side == 'buy' and top_price > price:
                    break
                if side == 'sell' and top_price < price:
                    break

            trade_qty = min(remaining, book[top_id]['qty'])

            if side == 'buy':
                trades.append([oid, top_id, top_price, trade_qty])
            else:
                trades.append([top_id, oid, top_price, trade_qty])

            remaining -= trade_qty
            book[top_id]['qty'] -= trade_qty

            if book[top_id]['qty'] == 0:
                book[top_id]['status'] = 'done'
                heapq.heappop(opp_heap)

        if typ == 'limit' and remaining > 0:
            add_resting(oid, side, price, remaining, seq)
        elif typ == 'limit' and remaining == 0:
            book[oid] = {'side': side, 'price': price, 'qty': 0, 'status': 'done', 'seq': seq}
        else:
            # ioc or market: discard remainder
            book[oid] = {'side': side, 'price': price, 'qty': 0, 'status': 'done', 'seq': seq}

    return trades

